// Transforme la réponse JSON-stat d'Eurostat Comext en lignes pour ie.flux_commerce
// (une ligne par pays déclarant, origine et mois, avec valeur en € et poids en kg).
const d = $input.first().json;
if (!d.id || !d.value) {
  // Comext indisponible ou requête refusée : on continue avec Comtrade et le Sheet, l'erreur reste visible ici.
  return [{ json: { lignes: [], erreur: 'Comext : ' + JSON.stringify(d).slice(0, 300) } }];
}
const ANNEES_GARDEES = 5;
const depuis = String(new Date().getFullYear() - ANNEES_GARDEES);
const dims = d.id.map((k) => k.toLowerCase());
const codes = d.id.map((k) => {
  const liste = [];
  for (const [code, pos] of Object.entries(d.dimension[k].category.index)) liste[pos] = code;
  return liste;
});
const clePartenaire = d.id.find((k) => k.toLowerCase() === 'partner');
const nomsPartenaires = d.dimension[clePartenaire]?.category?.label ?? {};

const lignes = new Map();
for (const [position, v] of Object.entries(d.value)) {
  if (v === null || v === undefined) continue;
  let reste = Number(position);
  const obs = {};
  for (let i = dims.length - 1; i >= 0; i--) {
    obs[dims[i]] = codes[i][reste % d.size[i]];
    reste = Math.floor(reste / d.size[i]);
  }
  const periode = String(obs.time).replace('M', '-'); // « 2025M08 » ou « 2025-08 » → « 2025-08 »
  if (periode < depuis) continue;
  const cle = [obs.reporter, obs.partner, obs.product, periode].join('|');
  const l = lignes.get(cle) ?? {
    source: 'comext', flux: obs.flow === '2' ? 'export' : 'import',
    declarant: obs.reporter, partenaire: obs.partner, partenaire_nom: nomsPartenaires[obs.partner] ?? '',
    produit_code: obs.product, periode, valeur: null, devise: 'EUR', poids_kg: null,
  };
  const indicateur = String(obs.indicators ?? '');
  if (/VALUE_IN_EUR/.test(indicateur)) l.valeur = v;
  else if (/QUANTITY_IN_100KG/.test(indicateur)) l.poids_kg = v * 100;
  else if (/QUANTITY_IN_KG/.test(indicateur)) l.poids_kg = v;
  lignes.set(cle, l);
}
return [{ json: { lignes: [...lignes.values()].filter((l) => l.valeur !== null || l.poids_kg !== null) } }];

// Exportations de mangues (SH 080450) déclarées par la Côte d'Ivoire et le Sénégal, par pays de destination.
// Comtrade renvoie parfois plusieurs lignes par destination (mode de transport, régime douanier) : on garde le total.
const r = $input.first().json;
const data = Array.isArray(r.data) ? r.data : [];
const total = (x) => [x.partner2Code, x.motCode].every((c) => c === undefined || c === null || Number(c) === 0)
  && (x.customsCode === undefined || x.customsCode === null || x.customsCode === 'C00');
const lignes = new Map();
for (const x of data.filter(total)) {
  if (x.primaryValue === null || x.primaryValue === undefined) continue;
  const l = {
    source: 'comtrade', flux: x.flowCode === 'M' ? 'import' : 'export',
    declarant: x.reporterISO, partenaire: x.partnerISO, partenaire_nom: x.partnerDesc ?? '',
    produit_code: String(x.cmdCode), periode: String(x.period),
    valeur: x.primaryValue, devise: 'USD', poids_kg: x.netWgt ?? null,
  };
  lignes.set([l.declarant, l.partenaire, l.periode].join('|'), l);
}
const sortie = { lignes: [...lignes.values()] };
if (!data.length) sortie.erreur = 'Comtrade : aucune donnée. ' + JSON.stringify(r).slice(0, 300);
return [{ json: sortie }];

// Résume les flux en quelques lignes de chiffres pour l'IA (l'IA ne calcule rien elle-même).
const { flux = [], infos = [] } = $input.first().json;
const fr = flux.filter((f) => f.source === 'comext' && f.declarant === 'FR');
if (!fr.length) throw new Error("Aucune donnée Comext en base : vérifiez le nœud « Eurostat Comext ».");

const t = (kg) => `${Math.round((kg ?? 0) / 1000).toLocaleString('fr-FR')} t`;
const me = (v) => `${((v ?? 0) / 1e6).toFixed(2).replace('.', ',')} M€`;
const prix = (v, kg) => (v && kg ? `${(v / kg).toFixed(2).replace('.', ',')} €/kg` : 'prix n.d.');

// Importations françaises, mois par mois et par origine
const mois = [...new Set(fr.map((f) => f.periode))].sort();
const dernier = mois.at(-1);
const [a, m] = dernier.split('-');
const memeMoisAnPasse = `${Number(a) - 1}-${m}`;
const ligneMois = (p) => fr.filter((f) => f.periode === p)
  .map((f) => `${f.partenaire_nom || f.partenaire} ${t(f.poids_kg)}, ${me(f.valeur)}, ${prix(f.valeur, f.poids_kg)}`)
  .join(' ; ');
const serie = mois.slice(-13).map((p) => `${p} : ${ligneMois(p)}`).join('\n');

// Total UE pour situer la France
const ue = flux.filter((f) => f.source === 'comext' && f.declarant !== 'FR' && f.periode === dernier);
const ligneUE = ue.length ? `Total UE ${dernier} : ${ue.map((f) => `${f.partenaire_nom || f.partenaire} ${t(f.poids_kg)}`).join(' ; ')}` : '';

// Destinations des exportations ivoiriennes et sénégalaises (Comtrade, annuel)
const ct = flux.filter((f) => f.source === 'comtrade' && f.partenaire !== 'W00');
const destinations = [...new Set(ct.map((f) => f.declarant))].map((pays) => {
  const lignes = ct.filter((f) => f.declarant === pays);
  const annee = lignes.map((f) => f.periode).sort().at(-1);
  const top = lignes.filter((f) => f.periode === annee).sort((x, y) => y.valeur - x.valeur).slice(0, 5)
    .map((f) => `${f.partenaire_nom || f.partenaire} ${(f.valeur / 1e6).toFixed(1).replace('.', ',')} M$`);
  return `Exportations ${pays} ${annee}, 5 premières destinations : ${top.join(', ')}`;
}).join('\n');

const notes = infos.slice(-10).map((i) => `${i.date_info} [${i.categorie}] ${i.titre}${i.detail ? ' : ' + i.detail : ''}`
  + `${i.valeur !== null ? ` (${i.valeur} ${i.unite})` : ''}${i.source ? ` — ${i.source}` : ''}`).join('\n');

return [{ json: {
  mois: dernier,
  donnees: [`Importations françaises de mangues (Eurostat Comext), le plus récent en dernier :`, serie,
    ligneUE, destinations, notes ? `Infos saisies par l'analyste :\n${notes}` : ''].filter(Boolean).join('\n\n'),
  comparaison: ligneMois(memeMoisAnPasse) || null,
  resume_dernier: ligneMois(dernier),
} }];

parameters.text:
=Tu es analyste de marché pour des exportateurs de mangues d'Afrique de l'Ouest (Côte d'Ivoire, Sénégal) qui vendent en France.

{{ $json.donnees }}

Écris une note de 4 phrases maximum, en français simple, pour un exportateur :
1. les volumes importés par la France le dernier mois ({{ $json.mois }}) par origine, comparés au même mois de l'année précédente s'il figure dans les données ;
2. le prix moyen à l'import (€/kg) et son évolution ;
3. ce que disent les destinations des exportations ivoiriennes et sénégalaises (concurrence ou débouchés hors France) ;
4. si des infos de l'analyste sont fournies, celle qui compte le plus pour la prochaine expédition.

Règles : n'utilise que les chiffres ci-dessus, n'invente aucune cause ni aucun chiffre. Les données Comext ont environ deux mois de retard : dis « en {{ $json.mois }} », jamais « ce mois-ci ». Pas de titre, pas de liste, pas de mise en forme.

parameters.jsCode:
// Garde le texte de l'IA ; s'il est vide (modèle gratuit indisponible), écrit une note simple sans IA.
const p = $('Préparer la note du mois').first().json;
const texteIA = String($json.text ?? '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (texteIA) return [{ json: { mois: p.mois, texte: texteIA, modele: 'openrouter/free' } }];
let texte = `En ${p.mois}, importations françaises de mangues : ${p.resume_dernier}.`;
if (p.comparaison) texte += ` Un an plus tôt : ${p.comparaison}.`;
return [{ json: { mois: p.mois, texte, modele: 'calcul automatique (IA indisponible)' } }];

// Lit l'onglet « cotations » du Google Sheet (mêmes règles que le formulaire du workflow 01).
// Une ligne incomplète ou fausse est ignorée et signalée dans « erreurs », sans bloquer les autres.
const texte = (v) => String(v ?? '').trim();
const nombre = (v) => { const n = Number(texte(v).replace(/\s/g, '').replace(',', '.')); return texte(v) === '' || Number.isNaN(n) ? null : n; };
// Accepte 2026-10-09, 09/10/2026 et le numéro de série de Google Sheets.
const date = (v) => {
  const s = texte(v);
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Number(s) * 864e5).toISOString().slice(0, 10);
  return null;
};

const lignes = [];
const erreurs = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  if (!texte(r.date) && !texte(r.prix_min)) return; // ligne vide
  const d = date(r.date);
  const min = nombre(r.prix_min);
  const max = nombre(r.prix_max);
  const pb = !d ? 'date invalide' : !(min > 0) || !(max > 0) ? 'prix manquant' : min > max ? 'prix min > prix max'
    : !texte(r.marche) || !texte(r.origine) ? 'marché ou origine manquant' : '';
  if (pb) { erreurs.push(`Ligne ${i + 2} : ${pb}`); return; }
  lignes.push({
    date_cotation: d, marche: texte(r.marche), origine: texte(r.origine),
    variete: texte(r.variete), calibre: texte(r.calibre), prix_min: min, prix_max: max,
    source: texte(r.source) || 'RNM FranceAgriMer', source_url: texte(r.source_url) || null,
  });
});
return [{ json: { lignes, erreurs } }];

// Lit l'onglet « infos » du Google Sheet : exports Trade Map, infos terrain, réglementation…
// Chaque ligne reçoit une empreinte : modifier une ligne met à jour la même info au lieu d'en créer une autre.
const texte = (v) => String(v ?? '').trim();
const nombre = (v) => { const n = Number(texte(v).replace(/\s/g, '').replace(',', '.')); return texte(v) === '' || Number.isNaN(n) ? null : n; };
// Accepte 2026-10-09, 09/10/2026 et le numéro de série de Google Sheets.
const date = (v) => {
  const s = texte(v);
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Number(s) * 864e5).toISOString().slice(0, 10);
  return null;
};

const empreinte = (s) => { let h = 2166136261; for (const c of s) h = Math.imul(h ^ c.codePointAt(0), 16777619) >>> 0; return h.toString(16); };
const lignes = [];
const erreurs = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  if (!texte(r.titre) && !texte(r.date)) return;
  const d = date(r.date);
  if (!d || !texte(r.titre)) { erreurs.push(`Ligne ${i + 2} : date ou titre manquant`); return; }
  lignes.push({
    id_ligne: empreinte([d, texte(r.titre).toLowerCase(), texte(r.pays).toLowerCase(), texte(r.source).toLowerCase()].join('|')),
    date_info: d, categorie: texte(r.categorie) || 'autre', produit: texte(r.produit) || 'mangue',
    pays: texte(r.pays), titre: texte(r.titre), detail: texte(r.detail), valeur: nombre(r.valeur),
    unite: texte(r.unite), source: texte(r.source), source_url: texte(r.source_url) || null,
  });
});
return [{ json: { lignes, erreurs } }];

// Rassemble la série hebdomadaire en un seul texte pour l'IA.
const lignes = $input.all().map((i) => i.json).filter((r) => r.semaine);
if (!lignes.length) throw new Error('Aucune cotation en base.');
const tableau = lignes
  .map((r) => `${r.semaine} (${r.cle}) : ${Number(r.prix).toFixed(2)} €/kg, ${r.nb_cotations} cotation(s)`)
  .join('\n');
const d = lignes.at(-1);
const p = lignes.at(-2);
return [{ json: {
  cle_derniere: d.cle,
  donnees: tableau,
  semaine: d.semaine,
  prix: Number(d.prix),
  prix_precedent: p ? Number(p.prix) : null,
} }];

parameters.text:
=Tu es analyste de marché pour des exportateurs de mangues d'Afrique de l'Ouest (Côte d'Ivoire, Sénégal) qui vendent en France.

Voici le prix moyen grossiste de la mangue, semaine par semaine (le plus récent en dernier) :
{{ $json.donnees }}

Écris un commentaire de 3 phrases maximum, en français simple, pour un exportateur :
1. l'évolution de la dernière semaine par rapport à la précédente (en %) ;
2. le niveau actuel par rapport à la moyenne de la période ;
3. un conseil prudent pour la prochaine expédition.

Règles : n'utilise que les chiffres ci-dessus, n'invente aucune cause ni aucun chiffre. S'il n'y a qu'une semaine, dis simplement que la tendance n'est pas encore mesurable. Pas de titre, pas de liste, pas de mise en forme.

parameters.jsCode:
// Garde le texte de l'IA ; s'il est vide (modèle gratuit indisponible ou réponse vide),
// écrit un commentaire simple calculé à partir des seuls chiffres, sans IA.
const p = $('Préparer le prompt (Sheet)').first().json;
const texteIA = String($json.text ?? '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .trim();
if (texteIA) return [{ json: { cle: p.cle_derniere, texte: texteIA, modele: 'openrouter/free' } }];

const fmt = (n) => n.toFixed(2).replace('.', ',');
let texte = `Semaine ${p.semaine.slice(1)} : ${fmt(p.prix)} €/kg en moyenne.`;
if (p.prix_precedent) {
  const v = ((p.prix - p.prix_precedent) / p.prix_precedent) * 100;
  texte += v === 0
    ? ` Prix stable par rapport à la semaine précédente.`
    : ` ${v > 0 ? 'Hausse' : 'Baisse'} de ${Math.abs(v).toFixed(1).replace('.', ',')} % par rapport à la semaine précédente (${fmt(p.prix_precedent)} €/kg).`;
} else {
  texte += " C'est la première semaine suivie : la tendance n'est pas encore mesurable.";
}
return [{ json: { cle: p.cle_derniere, texte, modele: 'calcul automatique (IA indisponible)' } }];
